def generate_next(n):
    if n < 10:
        return n + n
    else:
        product = 1
        has_non_zero_digit = False
        for digit in str(n):
            if digit != '0':
                product *= int(digit)
                has_non_zero_digit = True
        return n + product if has_non_zero_digit else n

